declare(strict_types=1);

namespace App\Repository;

use App\Entity\GamePlayers;
use App\Enum\GameStatus;
use Doctrine\DBAL\LockMode;
use Doctrine\DBAL\ParameterType;
use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository;
use Doctrine\ORM\QueryBuilder;
use Doctrine\Persistence\ManagerRegistry;

/**
 * @extends ServiceEntityRepository<GamePlayers>
 * This class was generated by the Doctrine ORM. Add your own custom
 */
final class GamePlayersRepository extends ServiceEntityRepository implements GamePlayersRepositoryInterface
{
    /**
     * @param ManagerRegistry $registry
     *
     */
    public function __construct(ManagerRegistry $registry)
    {
        parent::__construct($registry, GamePlayers::class);
    }

    /**
     * Find players with user information for a specific game
     *
     * @param int $gameId
     *
     * @return array<int, array{id:int|null,name:string|null,position:int|null,placement:int|null,isGuest:bool}>
     */
    #[\Override]
    public function findPlayersWithUserInfo(int $gameId): array
    {
        $players = $this->createSeatsQueryBuilder($gameId)
            ->select(
                'u.id as id',
                PlayerDisplayNameExpression::dql('gp', 'u').' as name',
                'gp.position as position',
                'gp.placement as placement',
                'u.isGuest as isGuest'
            )
            ->innerJoin('gp.player', 'u')
            ->getQuery()
            ->getArrayResult();

        return array_map(static function (array $player): array {
            return [
                'id' => isset($player['id']) ? (int) $player['id'] : null,
                'name' => $player['name'] ?? null,
                'position' => isset($player['position']) ? (int) $player['position'] : null,
                'placement' => isset($player['placement']) ? (int) $player['placement'] : null,
                'isGuest' => isset($player['isGuest']) ? (bool) $player['isGuest'] : false,
            ];
        }, $players);
    }

    /**
     * Check if a player already joined the game
     *
     * @param int $gameId
     * @param int $playerId
     *
     * @return bool
     */
    #[\Override]
    public function isPlayerInGame(int $gameId, int $playerId): bool
    {
        $count = $this->count([
            'game' => $gameId,
            'player' => $playerId,
        ]);

        return $count > 0;
    }

    /**
     * @param int $gameId
     * @param int $playerId
     *
     * @return bool
     */
    #[\Override]
    public function isPlayerInGameForShare(int $gameId, int $playerId): bool
    {
        $seats = $this->createQueryBuilder('gp')
            ->select('gp.gamePlayerId')
            ->andWhere('gp.game = :gameId')
            ->andWhere('gp.player = :playerId')
            ->setParameter('gameId', $gameId)
            ->setParameter('playerId', $playerId)
            ->setMaxResults(1)
            ->getQuery()
            ->setLockMode(LockMode::PESSIMISTIC_READ)
            ->getScalarResult();

        return [] !== $seats;
    }

    /**
     * @return GamePlayers[]
     *
     * @param int $gameId
     */
    #[\Override]
    public function findByGameId(int $gameId): array
    {
        return $this->createSeatsQueryBuilder($gameId)
            ->addSelect('player')
            ->innerJoin('gp.player', 'player')
            ->getQuery()
            ->getResult();
    }

    /**
     * @param list<int> $gameIds
     *
     * @return array<int, list<GamePlayers>> seats per game id, in seat order
     */
    #[\Override]
    public function findByGameIds(array $gameIds): array
    {
        if ([] === $gameIds) {
            return [];
        }

        /** @var list<GamePlayers> $seats */
        $seats = $this->createSeatOrderQueryBuilder()
            ->addSelect('game', 'player')
            ->innerJoin('gp.game', 'game')
            ->innerJoin('gp.player', 'player')
            ->andWhere('gp.game IN (:gameIds)')
            ->setParameter('gameIds', $gameIds)
            ->getQuery()
            ->getResult();

        $seatsByGameId = [];
        foreach ($seats as $seat) {
            $seatsByGameId[(int) $seat->getGame()?->getGameId()][] = $seat;
        }

        return $seatsByGameId;
    }

    /**
     * @return GamePlayers[]
     *
     * @param int $gameId
     */
    #[\Override]
    public function findByGameIdForShare(int $gameId): array
    {
        return $this->createSeatsQueryBuilder($gameId)
            ->getQuery()
            ->setLockMode(LockMode::PESSIMISTIC_READ)
            ->getResult();
    }

    /**
     * @param int    $gameId
     * @param string $name
     *
     * @return bool
     */
    #[\Override]
    public function existsNameInGame(int $gameId, string $name): bool
    {
        $normalizedName = trim($name, ' ');
        $normalizedName = function_exists('mb_strtolower')
            ? mb_strtolower($normalizedName)
            : strtolower($normalizedName);

        if ('' === $normalizedName) {
            return false;
        }

        $connection = $this->getEntityManager()->getConnection();
        $userTable = $connection->getDatabasePlatform()->quoteSingleIdentifier('user');

        $result = $connection->fetchOne(
            sprintf(
                <<<'SQL'
SELECT 1
FROM game_players gp
INNER JOIN %s u ON u.id = gp.player_id
WHERE gp.game_id = :gameId
    AND LOWER(TRIM(%s)) = :name
LIMIT 1
SQL,
                $userTable,
                PlayerDisplayNameExpression::sql('gp', 'u'),
            ),
            [
                'gameId' => $gameId,
                'name' => $normalizedName,
            ],
            [
                'gameId' => ParameterType::INTEGER,
                'name' => ParameterType::STRING,
            ]
        );

        return false !== $result;
    }

    /**
     * @param int $gameId
     *
     * @return int
     */
    #[\Override]
    public function findNextPositionForGame(int $gameId): int
    {
        $row = $this->getEntityManager()->getConnection()->fetchAssociative(
            <<<'SQL'
SELECT
    MAX(gp.position) AS maxPosition,
    COUNT(gp.game_player_id) AS playersCount
FROM game_players gp
WHERE gp.game_id = :gameId
FOR SHARE
SQL,
            ['gameId' => $gameId],
            ['gameId' => ParameterType::INTEGER]
        );

        $maxPosition = $row['maxPosition'] ?? null;
        if (null !== $maxPosition) {
            return (int) $maxPosition + 1;
        }

        return (int) ($row['playersCount'] ?? 0) + 1;
    }

    /**
     * @param int $gameId
     *
     * @return array<int, array{playerId:int,name:string,position:int|null,placement:int|null,score:int|null,isGuest:bool}>
     */
    #[\Override]
    public function findGameStatePlayersByGameId(int $gameId): array
    {
        $rows = $this->createSeatsQueryBuilder($gameId)
            ->select(
                'player.id AS playerId',
                PlayerDisplayNameExpression::dql('gp', 'player').' AS name',
                'gp.position AS position',
                'gp.placement AS placement',
                'gp.score AS score',
                'player.isGuest AS isGuest'
            )
            ->innerJoin('gp.player', 'player')
            ->getQuery()
            ->getArrayResult();

        return array_map(static function (array $row): array {
            return [
                'playerId' => (int) $row['playerId'],
                'name' => (string) $row['name'],
                'position' => isset($row['position']) ? (int) $row['position'] : null,
                'placement' => isset($row['placement']) ? (int) $row['placement'] : null,
                'score' => isset($row['score']) ? (int) $row['score'] : null,
                'isGuest' => isset($row['isGuest']) ? (bool) $row['isGuest'] : false,
            ];
        }, $rows);
    }

    /**
     * @param int $playerId
     *
     * @return array{gameId:int,status:GameStatus}|null
     */
    #[\Override]
    public function findCurrentGameForPlayer(int $playerId): ?array
    {
        /** @var array{gameId:int|string,status:GameStatus}|null $row */
        $row = $this->createQueryBuilder('gp')
            ->select('game.gameId AS gameId', 'game.status AS status')
            ->innerJoin('gp.game', 'game')
            ->andWhere('gp.player = :playerId')
            ->andWhere('game.status IN (:statuses)')
            ->setParameter('playerId', $playerId)
            ->setParameter('statuses', [GameStatus::Lobby, GameStatus::Started])
            ->orderBy('gp.gamePlayerId', 'DESC')
            ->setMaxResults(1)
            ->getQuery()
            ->getOneOrNullResult();

        if (null === $row) {
            return null;
        }

        return ['gameId' => (int) $row['gameId'], 'status' => $row['status']];
    }

    /**
     * The game's seats in seat order.
     *
     * @param int $gameId
     *
     * @return QueryBuilder
     */
    private function createSeatsQueryBuilder(int $gameId): QueryBuilder
    {
        return $this->createSeatOrderQueryBuilder()
            ->andWhere('gp.game = :gameId')
            ->setParameter('gameId', $gameId);
    }

    /**
     * Seats in turn order, the same order as TurnOrder::compare().
     *
     * @return QueryBuilder
     */
    private function createSeatOrderQueryBuilder(): QueryBuilder
    {
        return $this->createQueryBuilder('gp')
            ->orderBy('CASE WHEN gp.position IS NULL THEN 1 ELSE 0 END', 'ASC')
            ->addOrderBy('gp.position', 'ASC')
            ->addOrderBy('gp.gamePlayerId', 'ASC');
    }
}
